334: function computeLayout() {
335:   const prevW = W, prevH = H, prevFloor = floorY;
336:   W = window.innerWidth;
337:   H = window.innerHeight;
338:   DPR = Math.min(window.devicePixelRatio || 1, 2);
339:   el.canvas.width = Math.round(W * DPR);
340:   el.canvas.height = Math.round(H * DPR);
341:   el.canvas.style.width = W + 'px';
342:   el.canvas.style.height = H + 'px';
343: 
344:   isTouch = window.matchMedia('(pointer: coarse)').matches || (navigator.maxTouchPoints || 0) > 0;
345:   document.body.classList.toggle('touch', isTouch);
346:   S = clamp(Math.sqrt(W * H) / 860, 0.66, 1.3);
347:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
348:   arenaTop = isTouch ? 78 : 96;
349:   floorY = H - apron;
350:   const margin = isTouch ? 14 : 24;
351:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
