356:   skyGrad.addColorStop(0.64, '#f56d73');
357:   skyGrad.addColorStop(0.85, '#ffb35e');
358:   skyGrad.addColorStop(1, '#ffe29a');
359:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
360:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
361:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
362:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
363: 
364:   rebuildDecor();
365:   if (prevW && (prevW !== W || prevH !== H)) {
366:     const sx = W / prevW;
367:     const sy = H / prevFloor;
368:     for (const p of players) {
369:       p.x *= sx;
370:       p.y = prevFloor ? p.y * sy : floorY;
371:       p.y = Math.min(p.y, floorY);
372:     }
373:     for (const b of balls) { b.x *= sx; b.y *= sy; }
374:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
375:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
