388:   // Keep the lowest ledge above a brawler's head (plus badge) and keep every
389:   // step within a single jump. Short/landscape screens get fewer ledges rather
390:   // than a cramped stack that clips through the fighters.
391:   const step = 125 * S;
392:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
