397:   // Chain the platforms horizontally so each one overlaps the next.
398:   const xs = [arena.left + bw * 0.05];
399:   for (let i = 1; i < levels; i++) {
400:     xs[i] = Math.min(xs[i - 1] + w[i - 1] - w[i] * 0.34, arena.right - w[i] - 10);
401:   }
