362: /* ------------------------------ input ------------------------------ */
363: const keys = new Set();
364: const touchAxes = [0, 0];          // analog joystick output, -1..1
365: const joysticks = [];
366: const pointerOwners = new Map();
367: const PLAYER_KEYS = [
368:   { left: ['KeyA'], right: ['KeyD'], jump: ['KeyW'], throw: ['Space'] },
369:   { left: ['ArrowLeft'], right: ['ArrowRight'], jump: ['ArrowUp'], throw: ['Enter', 'Numpad0'] },
370: ];
371: function hasAny(code, list) { return list.includes(code); }
372: function playerForKey(code) {
373:   for (let i = 0; i < 2; i++) {
374:     const m = PLAYER_KEYS[i];
375:     if (hasAny(code, m.left) || hasAny(code, m.right) || hasAny(code, m.jump) || hasAny(code, m.throw)) return { i, action: hasAny(code, m.left) ? 'left' : hasAny(code, m.right) ? 'right' : hasAny(code, m.jump) ? 'jump' : 'throw' };
376:   }
377:   return null;
378: }
379: function isModalOpen() {
380:   return !el.screenArcade.classList.contains('hidden') || !el.screenHow.classList.contains('hidden');
381: }
382: function getInputDir(p) {
383:   if (p.ai) return p.aiMove;
384:   let dir = 0;
385:   if (p.idx === 0) {
386:     if (keys.has('KeyA')) dir--;
387:     if (keys.has('KeyD')) dir++;
388:   } else {
389:     if (keys.has('ArrowLeft')) dir--;
390:     if (keys.has('ArrowRight')) dir++;
391:   }
392:   const axis = touchAxes[p.idx];
393:   if (axis) dir += axis;
394:   return clamp(dir, -1, 1);
395: }
396: function doJump(p, strength = 1) {
397:   if (!p || p.ko) return;
398:   p.vy = -jumpSpeedFor() * strength;
399:   p.onGround = false;
400:   p.coyote = 0;
401:   p.jumpBuffer = 0;
402:   if (p.wasGround) { dust(p.x, p.y, 4); sfx.jump(); }
403:   else {
404:     dust(p.x, p.y - 15 * S, 4);
405:     burst(p.x, p.y - 20 * S, P_COLORS[p.idx], 6, 0.5, 'dot');
406:     sfx.jump();
407:   }
408: }
409: function queueJump(p) {
410:   if (!p || p.ko) return;
411:   if (state !== 'play' && state !== 'title') return;
412:   p.jumpBuffer = 0.13;
413: }
414: function requestThrow(p) {
415:   if (!p || p.ko) return;
416:   if (state !== 'play' && state !== 'title') return;
417:   beginThrow(p);
418: }
419: function releaseThrowInput(p) {
420:   if (!p) return;
421:   if (p.charging) releaseThrow(p);
422: }
423: 
424: function onKeyDown(e) {
425:   ensureAudio();
426:   if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Enter'].includes(e.code)) e.preventDefault();
427:   if (e.repeat) return;
428:   keys.add(e.code);
429: 
430:   if (isModalOpen()) {
431:     if (e.code === 'Escape') {
432:       if (!el.screenHow.classList.contains('hidden')) closeHow();
433:       else closeArcade();
434:     }
435:     return;
436:   }
437:   if (state === 'title') {
438:     if (e.code === 'Enter' || e.code === 'Space') { sfx.ui(); newMatch('2p', titleChars); }
439:     return;
440:   }
441:   if (state === 'matchEnd') {
442:     if (endShown && (e.code === 'Enter' || e.code === 'Space')) rematch();
443:     return;
444:   }
445:   if (e.code === 'Escape') {
446:     if (paused) pauseGame(false);
447:     else pauseGame(true);
448:     return;
449:   }
450:   if (e.code === 'KeyM') { setMuted(!profile.muted); return; }
451:   if (paused) return;
452: 
453:   const pk = playerForKey(e.code);
454:   if (!pk) return;
455:   const p = players[pk.i];
456:   if (!p) return;
457:   if (pk.action === 'jump') queueJump(p);
458:   else if (pk.action === 'throw' && state === 'play') requestThrow(p);
459: }
460: 
461: function onKeyUp(e) {
462:   keys.delete(e.code);
463:   const pk = playerForKey(e.code);
464:   if (!pk) return;
465:   const p = players[pk.i];
466:   if (!p) return;
467:   if (pk.action === 'throw') releaseThrowInput(p);
468:   if (pk.action === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
469: }
