471: function bindTouch() {
472:   document.querySelectorAll('.tbtn[data-act]').forEach(btn => {
473:     const pad = btn.closest('.pad');
474:     const pIdx = Number(pad.dataset.player);
475:     const act = btn.dataset.act;
476:     const down = e => {
477:       e.preventDefault();
478:       ensureAudio();
479:       if (state !== 'play' && state !== 'title') return;
480:       if (paused) return;
481:       btn.classList.add('pressed');
482:       pointerOwners.set(e.pointerId, { pIdx, act, btn });
483:       try { btn.setPointerCapture?.(e.pointerId); } catch {}
484:       const p = players[pIdx];
485:       if (!p) return;
486:       if (act === 'jump') queueJump(p);
487:       if (act === 'throw') {
488:         const moving = Math.abs(getInputDir(p)) > 0.15;
489:         requestThrow(p);
490:         if (!moving) setTimeout(() => releaseThrowInput(p), 90);
491:       }
492:     };
493:     const up = e => {
494:       const own = pointerOwners.get(e.pointerId);
495:       if (!own || own.pIdx !== pIdx) return;
496:       pointerOwners.delete(e.pointerId);
497:       btn.classList.remove('pressed');
498:       const p = players[pIdx];
499:       if (!p) return;
500:       if (act === 'throw') releaseThrowInput(p);
501:       if (act === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
502:     };
503:     btn.addEventListener('pointerdown', down);
504:     btn.addEventListener('pointerup', up);
505:     btn.addEventListener('pointercancel', up);
506:     btn.addEventListener('lostpointercapture', up);
507:     btn.addEventListener('contextmenu', e => e.preventDefault());
508:   });
509: }
