511: /* ------------------------------ virtual joysticks ------------------------------ */
512: function bindJoysticks() {
513:   joysticks.length = 0;
514:   document.querySelectorAll('#touch .joystick').forEach(joyEl => {
515:     const pad = joyEl.closest('.pad');
516:     const pIdx = Number(pad.dataset.player);
517:     const base = joyEl.querySelector('.stick-base');
518:     const knob = joyEl.querySelector('.stick-knob');
519:     const j = { el: joyEl, knob, pIdx, pointerId: null, max: 1, jumpLatch: false };
520:     joysticks.push(j);
521: 
522:     const centerOf = () => {
523:       const r = base.getBoundingClientRect();
524:       j.max = Math.max(1, r.width * 0.3);
525:       return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
526:     };
527:     const setAxis = (dx, dy) => {
528:       const raw = Math.hypot(dx, dy);
529:       const scale = raw > j.max ? j.max / raw : 1;
530:       const kx = dx * scale, ky = dy * scale;
531:       knob.style.transform = `translate(-50%, -50%) translate(${kx}px, ${ky}px)`;
532:       const x = clamp(kx / j.max, -1, 1);
533:       const dead = 0.16;
534:       touchAxes[pIdx] = Math.sign(x) * clamp((Math.abs(x) - dead) / (1 - dead), 0, 1);
535:       // drop through platforms on downward flick
536:       if (ky > j.max * 0.5) {
537:         const pp = players[pIdx];
538:         if (pp) {
539:           pp.dropThrough = 0.25;
540:           if (pp.onGround && pp.y < floorY - 1) { pp.vy = 120 * S; pp.onGround = false; }
541:         }
542:       }
543:       // jump on upward flick
544:       if (ky < -j.max * 0.5 && !j.jumpLatch) {
545:         j.jumpLatch = true;
546:         const p = players[pIdx];
547:         if (p) queueJump(p);
548:       }
549:       if (ky > -j.max * 0.25) j.jumpLatch = false;
550:     };
551:     const release = e => {
552:       if (j.pointerId === null) return;
553:       if (e && e.pointerId !== undefined && e.pointerId !== j.pointerId) return;
554:       const p = players[pIdx];
555:       if (p && p.charging) {
556:         releaseThrow(p);
557:         p.needsMove = true;
558:       }
559:       j.pointerId = null;
560:       j.jumpLatch = false;
561:       touchAxes[pIdx] = 0;
562:       joyEl.classList.remove('active');
563:       knob.style.transform = 'translate(-50%, -50%)';
564:     };
565:     const canUse = () => (state === 'play' || state === 'title') && !paused;
566: 
567:     joyEl.addEventListener('pointerdown', e => {
568:       e.preventDefault();
569:       ensureAudio();
570:       if (!canUse() || j.pointerId !== null) return;
571:       j.pointerId = e.pointerId;
572:       joyEl.classList.add('active');
573:       try { joyEl.setPointerCapture(e.pointerId); } catch {}
574:       const c = centerOf();
575:       setAxis(e.clientX - c.x, e.clientY - c.y);
576:     });
577:     joyEl.addEventListener('pointermove', e => {
578:       if (j.pointerId !== e.pointerId) return;
579:       e.preventDefault();
580:       const c = centerOf();
581:       setAxis(e.clientX - c.x, e.clientY - c.y);
582:     });
583:     joyEl.addEventListener('pointerup', release);
584:     joyEl.addEventListener('pointercancel', release);
585:     joyEl.addEventListener('lostpointercapture', release);
586:     joyEl.addEventListener('contextmenu', e => e.preventDefault());
587:   });
588: }
589: 
590: function resetJoysticks() {
591:   touchAxes[0] = 0;
592:   touchAxes[1] = 0;
593:   for (const j of joysticks) {
594:     j.pointerId = null;
595:     j.jumpLatch = false;
596:     j.knob.style.transform = 'translate(-50%, -50%)';
597:   }
598:   pointerOwners.clear();
599:   document.querySelectorAll('.tbtn.pressed').forEach(b => b.classList.remove('pressed'));
600: }
601: 
602: /* ------------------------------ player update ------------------------------ */
603: function updatePlayer(p, dt) {
604:   if (!p) return;
605:   // timers
606:   p.throwCd = Math.max(0, p.throwCd - dt);
607:   p.throwAnim = Math.max(0, p.throwAnim - dt);
608:   p.catchAnim = Math.max(0, p.catchAnim - dt);
609:   p.invuln = Math.max(0, p.invuln - dt);
610:   p.hitstun = Math.max(0, p.hitstun - dt);
611:   p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
612:   p.dropThrough = Math.max(0, (p.dropThrough || 0) - dt);
613:   p.blinkTimer -= dt;
614:   if (p.blinkTimer <= 0) { p.blink = 0.11; p.blinkTimer = rand(2.2, 4.8); }
615:   p.blink = Math.max(0, p.blink - dt);
616:   if (p.ko) {
617:     p.koT += dt;
618:     p.vy += gravityFor() * dt;
619:     p.x += p.vx * dt;
620:     p.y += p.vy * dt;
621:     p.vx *= Math.pow(0.2, dt);
622:     if (p.y > floorY) { p.y = floorY; p.vy = 0; p.vx *= 0.7; }
623:     p.x = clamp(p.x, arena.left + 22 * S, arena.right - 22 * S);
624:     p.onGround = p.y >= floorY - 0.5;
625:     return;
626:   }
627: 
628:   if (p.ai && (state === 'play' || state === 'title')) updateAI(p, dt);
629: 
630:   const canControl = state === 'play' && !paused;
631:   let dir = canControl ? getInputDir(p) : 0;
632:   if (p.hitstun > 0) dir = 0;
633: 
634:   // drop through platforms on down input
635:   if (state === 'play' && canControl && !p.ai) {
636:     const downHeld = (p.idx === 0 && keys.has('KeyS')) || (p.idx === 1 && keys.has('ArrowDown'));
637:     if (downHeld) {
638:       p.dropThrough = 0.2;
639:       if (p.onGround && p.y < floorY - 1) { p.vy = 120 * S; p.onGround = false; }
640:     }
641:   }
642: 
643:   // auto-charge / auto-fire for human players
644:   if (state === 'play' && canControl && !p.ai && !p.ko && p.hitstun <= 0) {
645:     const moving = Math.abs(dir) > 0.15;
646:     if (moving) {
647:       if (p.needsMove) p.needsMove = false;
648:       if (!p.charging && p.throwCd <= 0 && !p.needsMove) beginThrow(p);
649:     }
650:   }
651: 
652:   // jump buffering
653:   if (p.jumpBuffer > 0 && canControl) {
654:     if (p.onGround || p.coyote > 0) { p.wasGround = true; doJump(p, 1); p.jumpsLeft = 1; }
655:     else if (p.jumpsLeft > 0) { p.jumpsLeft--; p.wasGround = false; doJump(p, 0.88); }
656:   }
657: 
658:   const maxSp = runSpeedFor() * (p.charging ? 0.58 : 1) * (p.hitstun > 0 ? 0.5 : 1);
659:   if (dir !== 0) {
660:     p.facing = Math.sign(dir) || p.facing;
661:     p.vx += dir * 2900 * S * dt;
662:     p.vx = clamp(p.vx, -maxSp, maxSp);
663:   } else {
664:     p.vx *= Math.pow(0.0009, dt);
665:     if (Math.abs(p.vx) < 4 * S) p.vx = 0;
666:   }
667: 
668:   if (p.charging && canControl) {
669:     p.charge = Math.min(1, p.charge + dt / 1.24);
670:     p.chargeFx = (p.chargeFx || 0) - dt;
671:     if (p.chargeFx <= 0) {
672:       p.chargeFx = 0.07;
673:       const h = handPoint(p);
674:       addParticle({
675:         x: h.x + rand(-14, 14) * S, y: h.y + rand(-14, 14) * S,
676:         vx: rand(-30, 30) * S, vy: rand(-70, -10) * S,
677:         life: rand(0.2, 0.45), size: rand(2, 4.5) * S,
678:         color: P_COLORS[p.idx], kind: 'dot', grav: -60 * S, drag: 0.92,
679:       });
680:     }
681:   } else {
682:     p.charge = 0;
683:   }
684: 
685:   // physics
686:   p.wasGround = p.onGround;
687:   const prevY = p.y;
688:   p.vy += gravityFor() * dt;
689:   p.vy = Math.min(p.vy, 1900 * S);
690:   p.x += p.vx * dt;
691:   p.y += p.vy * dt;
692:   p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
693: 
694:   p.onGround = false;
695:   p.platform = null;
696:   if (p.vy >= 0 && (p.dropThrough || 0) <= 0) {
697:     for (const pl of platforms) {
698:       if (prevY <= pl.y + 2 && p.y >= pl.y && p.y <= pl.y + pl.h + 30 * S &&
699:           p.x + 14 * S > pl.x + 3 && p.x - 14 * S < pl.x + pl.w - 3) {
700:         p.y = pl.y;
701:         p.vy = 0;
702:         p.onGround = true;
703:         p.jumpsLeft = 1;
704:         p.platform = pl;
705:         break;
706:       }
707:     }
708:   }
709:   if (p.y >= floorY) {
710:     p.y = floorY;
